      ["so much for","so viel zu","So much for the sunny weekend!","So viel zum sonnigen Wochenende!"],
      ["just my luck","typisch, mein Pech","The bus left a minute early – just my luck.","Der Bus fuhr eine Minute zu früh – typisch."],
      ["subtext","Subtext, unterschwellige Botschaft","Pay attention to the subtext of his email.","Achte auf die unterschwellige Botschaft in seiner Mail."],
      ["connotation","Nebenbedeutung","\"Cheap\" has a negative connotation.","„Cheap“ hat eine negative Nebenbedeutung."],
      ["euphemism","Beschönigung, Euphemismus","\"Let go\" is a euphemism for \"fired\".","„Let go“ ist eine Beschönigung für „gefeuert“."],
      ["to let someone go","jdn. entlassen (beschönigend)","The company let twenty people go.","Die Firma hat zwanzig Leute entlassen."],
      ["between jobs","gerade ohne Job (beschönigend)","He's between jobs at the moment.","Er ist gerade auf Jobsuche."],
      ["economical with the truth","nicht ganz ehrlich (beschönigend)","The salesman was economical with the truth.","Der Verkäufer hat es mit der Wahrheit nicht so genau genommen."],
      ["to pass away","verscheiden, sterben","Her grandfather passed away last year.","Ihr Großvater ist letztes Jahr verstorben."],
      ["senior citizen","Senior(in)","Senior citizens get a discount.","Senioren bekommen Rabatt."],
      ["collateral damage","Kollateralschaden","The job cuts were described as collateral damage.","Der Stellenabbau wurde als Kollateralschaden bezeichnet."],
      ["downsizing","Personalabbau","The downsizing affected every department.","Der Personalabbau betraf jede Abteilung."],
      ["rather","ziemlich (oft untertreibend)","That was rather unfortunate.","Das war ziemlich unglücklich."],
      ["a bit of a","ein ziemliches (untertreibend)","It was a bit of a disaster.","Das war eine ziemliche Katastrophe."],
      ["charming","reizend (oft ironisch)","Oh, charming! Thanks a lot.","Oh, reizend! Vielen Dank auch."],
      ["typical","typisch (genervt)","Typical! It always rains on my day off.","Typisch! An meinem freien Tag regnet es immer."],
      ["to have a dig at","sticheln gegen","He had a dig at my driving.","Er stichelte gegen meinen Fahrstil."],
      ["to keep a straight face","ernst bleiben","I could hardly keep a straight face.","Ich konnte mir das Lachen kaum verkneifen."],
      ["irony is lost on someone","jemand versteht die Ironie nicht","The irony was completely lost on him.","Die Ironie ging völlig an ihm vorbei."],
      ["wry","trocken, schief (Lächeln)","She gave a wry smile.","Sie lächelte schief."],
      ["droll","drollig, komisch","He has a rather droll way of telling stories.","Er hat eine ziemlich drollige Art, Geschichten zu erzählen."],
      ["quip","witzige Bemerkung","He answered with a quick quip.","Er antwortete mit einer schlagfertigen Bemerkung."],
      ["one-liner","Einzeiler, kurzer Witz","The comedian is famous for his one-liners.","Der Komiker ist für seine kurzen Witze bekannt."],
      ["punchline","Pointe","I always forget the punchline.","Ich vergesse immer die Pointe."],
      ["to crack a joke","einen Witz reißen","He cracked a joke to break the ice.","Er riss einen Witz, um das Eis zu brechen."],
      ["in jest","im Scherz","It was said in jest.","Es war im Scherz gesagt."],
      ["to be in stitches","sich kaputtlachen","The audience was in stitches.","Das Publikum lachte sich kaputt."],
      ["hilarious","urkomisch","The film was absolutely hilarious.","Der Film war absolut urkomisch."],
      ["cheeky","frech","That was a bit cheeky of you!","Das war ein bisschen frech von dir!"],
      ["facetious","albern, unpassend scherzhaft","Stop being facetious – this is serious.","Hör auf, Witze zu machen – das ist ernst."],
      ["mock","gespielt, Schein-","She raised her hands in mock surrender.","Sie hob die Hände in gespielter Kapitulation."],
      ["satire","Satire","The show is a satire on modern politics.","Die Sendung ist eine Satire auf die moderne Politik."],
      ["parody","Parodie","The video is a parody of a famous advert.","Das Video ist eine Parodie auf eine berühmte Werbung."],
      ["caricature","Karikatur","The film turns him into a caricature.","Der Film macht eine Karikatur aus ihm."],
      ["absurd","absurd","The situation was so absurd we had to laugh.","Die Situation war so absurd, dass wir lachen mussten."],
      ["slapstick","Slapstick","Children love slapstick comedy.","Kinder lieben Slapstick."],
      ["gallows humour","Galgenhumor","Nurses often rely on gallows humour.","Pflegekräfte greifen oft auf Galgenhumor zurück."],
      ["to see the funny side","es mit Humor nehmen","Luckily, he saw the funny side.","Zum Glück nahm er es mit Humor."],
      ["to have a laugh","Spaß haben, herumalbern","We were just having a laugh.","Wir haben nur herumgealbert."],
      ["no laughing matter","nicht zum Lachen","Losing your job is no laughing matter.","Den Job zu verlieren ist nicht zum Lachen."],
      ["not half bad","gar nicht übel","This wine is not half bad.","Dieser Wein ist gar nicht übel."],
      ["not the end of the world","nicht der Weltuntergang","Failing one exam is not the end of the world.","Eine Prüfung nicht zu bestehen ist nicht der Weltuntergang."],
      ["not too shabby","gar nicht schlecht","A ten percent raise? Not too shabby!","Zehn Prozent mehr Gehalt? Gar nicht schlecht!"],
      ["a bit of a nuisance","etwas lästig","The roadworks are a bit of a nuisance.","Die Bauarbeiten sind etwas lästig."],
      ["slightly inconvenient","etwas ungünstig (Untertreibung)","Missing the last train was slightly inconvenient.","Den letzten Zug zu verpassen war etwas ungünstig."],
      ["I've had better days","ich hatte schon bessere Tage","How am I? Well, I've had better days.","Wie es mir geht? Nun, ich hatte schon bessere Tage."],
      ["what a surprise","welch Überraschung (ironisch)","The train is late again – what a surprise.","Der Zug ist wieder zu spät – welch Überraschung."],
      ["oh, brilliant","na toll (ironisch)","Oh, brilliant – it's raining again.","Na toll – es regnet schon wieder."],
      ["thanks a bunch","vielen Dank auch (ironisch)","You ate my lunch? Thanks a bunch.","Du hast mein Mittagessen gegessen? Vielen Dank auch."],
      ["as if","als ob (ironisch)","Him, apologise? As if!","Er und sich entschuldigen? Als ob!"],
      ["yeah, right","ja, klar (ungläubig)","'I'll be on time tomorrow.' – 'Yeah, right.'","„Morgen bin ich pünktlich.“ – „Ja, klar.“"],
      ["to damn with faint praise","durch mageres Lob abwerten","Calling it 'adequate' is damning with faint praise.","Es „ausreichend“ zu nennen, ist vernichtendes mageres Lob."],
      ["a backhanded compliment","ein vergiftetes Kompliment","'You look good for your age' is a backhanded compliment.","„Für dein Alter siehst du gut aus“ ist ein vergiftetes Kompliment."],
      ["double entendre","Doppeldeutigkeit","The joke relies on a double entendre.","Der Witz beruht auf einer Doppeldeutigkeit."],
      ["to be economical with words","wortkarg sein","He's famously economical with words.","Er ist bekanntlich wortkarg."],
      ["somewhat challenging","etwas herausfordernd (beschönigend)","The project has been somewhat challenging.","Das Projekt war etwas herausfordernd."],
      ["vertically challenged","klein (scherzhaft)","As a vertically challenged person, I hate crowds.","Als kleiner Mensch hasse ich Menschenmengen."],
      ["to be let go","entlassen werden (beschönigend)","Twenty employees were let go last month.","Letzten Monat wurden zwanzig Mitarbeitende entlassen."],
      ["pre-owned","gebraucht (beschönigend)","We sell pre-owned luxury watches.","Wir verkaufen gebrauchte Luxusuhren."],
      ["passed over","übergangen","She was passed over for promotion again.","Sie wurde bei der Beförderung wieder übergangen."],
      ["a difference of opinion","eine Meinungsverschiedenheit","We had a slight difference of opinion.","Wir hatten eine kleine Meinungsverschiedenheit."],
      ["a frank exchange of views","ein offener Meinungsaustausch (= Streit)","The talks involved a frank exchange of views.","Bei den Gesprächen gab es einen offenen Meinungsaustausch."],
      ["to be tired and emotional","angetrunken (brit. scherzhaft)","The guest was a little tired and emotional.","Der Gast war etwas angeheitert."],
      ["to have a sense of occasion","Gespür für den Anlass haben","The host had a real sense of occasion.","Der Gastgeber hatte ein echtes Gespür für den Anlass."],
      ["self-effacing","bescheiden, zurückhaltend","She's modest and self-effacing.","Sie ist bescheiden und zurückhaltend."],
      ["to roll one's eyes","die Augen verdrehen","She rolled her eyes at his excuse.","Sie verdrehte bei seiner Ausrede die Augen."],
      ["poker-faced","mit unbewegter Miene","He told the joke completely poker-faced.","Er erzählte den Witz mit völlig unbewegter Miene."],
      ["light-hearted","unbeschwert, heiter","It was a light-hearted look at office life.","Es war ein heiterer Blick auf das Büroleben."],
      ["tongue-tied","sprachlos, gehemmt","I always get tongue-tied in front of her.","Vor ihr bin ich immer ganz gehemmt."],
      ["a running joke","ein Running Gag","His bad cooking became a running joke.","Sein schlechtes Kochen wurde zum Running Gag."],
      ["an in-joke","ein Insider-Witz","Sorry, it's an in-joke.","Sorry, das ist ein Insider-Witz."],
      ["to lighten the mood","die Stimmung auflockern","He told a story to lighten the mood.","Er erzählte eine Geschichte, um die Stimmung aufzulockern."],
      ["to laugh it off","etwas weglachen","She laughed off the criticism.","Sie lachte die Kritik einfach weg."]
